import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not username:
        raise ValueError("Username must be a non-empty string.")
    response = requests.get(URL + username)
    response.raise_for_status()
    data = response.json()
    normalized = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized[key] = value
    return normalized

from flask import Flask
from flask_restful import Resource, Api
import requests

def task_func(api_url, template_folder):
    if not api_url or not template_folder:
        raise ValueError("api_url and template_folder must be non-empty strings.")

    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalData(Resource):
        def get(self):
            response = requests.get(api_url)
            response.raise_for_status()
            return response.json()

    api.add_resource(ExternalData, '/data')

    return app
